// RubyEmbed.m
//
// The ruby/ resource folder is generated by `make -f apple/Makefile resources`
// (stdlib/ + rbconfig/<platform>/) and copied into the package's resource
// bundle; SWIFTPM_MODULE_BUNDLE is SwiftPM's accessor for that bundle.

#import "RubyEmbed.h"
#import <TargetConditionals.h>

static NSString *RubyEmbedPlatform(void) {
#if TARGET_OS_SIMULATOR
    return @"ios-simulator";
#elif TARGET_OS_IOS
    return @"ios";
#else
    return @"macos";
#endif
}

NSArray<NSString *> *RubyEmbedLoadPaths(void) {
    NSString *root = [SWIFTPM_MODULE_BUNDLE.resourcePath stringByAppendingPathComponent:@"ruby"];
    return @[
        [[root stringByAppendingPathComponent:@"rbconfig"] stringByAppendingPathComponent:RubyEmbedPlatform()],
        [root stringByAppendingPathComponent:@"stdlib"],
    ];
}
